/* 
   Fancy "Paper Wave" Shader with:
   1) Camera angle transforms in 2D, simulating a tilt/angle
   2) Different wave shapes (sine, noise, etc.)
   3) Blinn-Phong specular + diffuse + rim lighting
   4) Finite difference normal approximation
   5) Layered Z-sorting so front wave occludes waves behind

   Usage:
   - Paste into ShaderToy or your GLSL environment
   - Adjust #defines for camera angles, shape, etc.
   - Experiment with wave function for advanced shapes


    LICENSE: DO NOT USE WITHOUT PERMISSION 

*/

//////////////////////////////////////////////////////////////
// 1) PARAMETERS & GLOBALS
//////////////////////////////////////////////////////////////

// Wave & layering
#define NUM_WAVES        4.0    // number of wave layers
#define WAVE_SPACING     0.03    // vertical offset between consecutive waves
#define WAVE_FREQUENCY   6.0
#define WAVE_AMPLITUDE   0.25
#define BAND_THICKNESS   0.40   // thickness of each "paper" wave
#define ANIMATION_SPEED  0.5

// Camera angle & transform
// We'll do a simple 2D rotation on uv to simulate "camera tilt" 
#define CAMERA_ANGLE     15.0   // in degrees

// Lighting intensities
#define AMBIENT_INTENSITY  0.2
#define DIFFUSE_INTENSITY  1.0
#define SPECULAR_INTENSITY 1.0
#define RIM_INTENSITY      1.6

// Specular exponent (Blinn-Phong)
#define SPECULAR_POWER     6.0

// Shadow settings (if you want to keep them)
#define ENABLE_SHADOWS     1    // set to 1 or 0
#define MAX_SHADOW_STEPS   8
#define SHADOW_STEP_SIZE   0.008
#define SHADOW_BIAS        0.0001

// Additional color params
vec3 colorFront = vec3(0.588,0.471,0.353);  
vec3 colorBack  = vec3(0.1, 0.1, 0.2);
vec3 bgColor    = vec3(0.05, 0.05, 0.07);

// Light direction for basic shading
vec3 lightDir   = normalize(vec3(1.000,0.10,0.100));

// A utility to convert degrees to radians
float deg2rad(float d) { return d * 3.14159 / 180.0; }

//////////////////////////////////////////////////////////////
// 2) CAMERA TRANSFORM
//////////////////////////////////////////////////////////////

// Apply a 2D rotation to (x,y) by angle degrees
vec2 cameraTransform(vec2 uv, float angleDeg)
{
    float a = deg2rad(angleDeg);
    float ca = cos(a);
    float sa = sin(a);
    // standard 2D rotation
    // [ x' ] = [  cos(a)  -sin(a) ] [ x ]
    // [ y' ]   [  sin(a)   cos(a) ] [ y ]
    float x = uv.x * ca - uv.y * sa;
    float y = uv.x * sa + uv.y * ca;
    return vec2(x, y);
}

//////////////////////////////////////////////////////////////
// 3) waveSDF: signed distance for wave shape
//    - We can customize the function shape here.
//////////////////////////////////////////////////////////////

float waveSDF(vec2 uv, float waveIndex, float time)
{
    // SHIFT each wave vertically
    float yShift = WAVE_SPACING * waveIndex;

    // WAVE: basic sine w/ extra noise
    float base = sin(uv.x * WAVE_FREQUENCY + time + waveIndex) * WAVE_AMPLITUDE;

    // Additional dynamic noise
    // e.g., a mild "ripple" from sin/cos combos
    float ripple = 0.1 * sin(3.0*(uv.x + waveIndex + time)) 
                 * cos(2.0*(uv.x - waveIndex - time));

    float waveCenter = base + ripple - yShift;

    // Distance from the wave line => band for thickness
    float distFromLine = uv.y - waveCenter;
    return abs(distFromLine) - BAND_THICKNESS;
}

//////////////////////////////////////////////////////////////
// 4) getZValue: define layering (front vs. back)
//////////////////////////////////////////////////////////////

float getZValue(float waveIndex)
{
    // waveIndex=0 => front (largest Z)
    // waveIndex=NUM_WAVES-1 => back (smallest Z)
    return (NUM_WAVES - waveIndex);
}

//////////////////////////////////////////////////////////////
// 5) FINITE DIFFERENCE NORMAL
//    More accurate than the single partial derivative approach
//////////////////////////////////////////////////////////////

vec3 computeNormal(vec2 uv, float waveIndex, float time)
{
    // Finite differences
    const float e = 0.001;

    // Dist at center
    float dC = waveSDF(uv, waveIndex, time);
    // Dist offsets
    float dX = waveSDF(uv + vec2(e, 0.0), waveIndex, time) - dC;
    float dY = waveSDF(uv + vec2(0.0, e), waveIndex, time) - dC;

    // Normal is approx (-dX, 1, -dY), flipping signs to taste
    // We'll treat the "vertical" axis as Y => so (nx, ny, nz) => ( -dX, 1, -dY ).
    vec3 n = normalize(vec3(-dX, 1.0, -dY));
    return n;
}

//////////////////////////////////////////////////////////////
// 6) SHADOW TRACE (optional)
//////////////////////////////////////////////////////////////

float shadowTrace(vec2 uv, float waveIndex, float time)
{
#if ENABLE_SHADOWS == 0
    return 1.0; // shadows disabled
#else
    // Project lightDir into 2D
    vec2 light2D = normalize(lightDir.xy + 0.001);

    float zCurrent = getZValue(waveIndex);
    vec2 pos = uv;

    for(int i=0; i<MAX_SHADOW_STEPS; i++)
    {
        pos += light2D * SHADOW_STEP_SIZE;

        // Check if a wave in front occludes
        for(float j=0.0; j<NUM_WAVES; j+=1.0)
        {
            float zVal = getZValue(j);
            if(zVal > zCurrent)
            {
                float d = waveSDF(pos, j, time);
                if(d < -SHADOW_BIAS)
                {
                    return 0.0; // in shadow
                }
            }
        }
    }
    return 1.0; // no shadow found
#endif
}

//////////////////////////////////////////////////////////////
// 7) BLINN-PHONG LIGHTING
//    with ambient, diffuse, specular, rim
//////////////////////////////////////////////////////////////

vec3 waveLighting(vec2 uv, float waveIndex, float time)
{
    // Normal from finite difference
    vec3 N = computeNormal(uv, waveIndex, time);
    // View direction (assuming viewer at +Z)
    vec3 V = normalize(vec3(0.0, 0.0, 1.0));
    // Light direction
    vec3 L = lightDir;
    // Half vector (Blinn)
    vec3 H = normalize(L + V);

    // Ambient
    float ambient = AMBIENT_INTENSITY;

    // Diffuse
    float diff = max(dot(N, L), 0.0) * DIFFUSE_INTENSITY;

    // Specular (Blinn-Phong)
    float spec = pow(max(dot(N, H), 0.0), SPECULAR_POWER) * SPECULAR_INTENSITY;

    // Rim lighting
    float rim = pow(1.0 - dot(N, V), 3.0) * RIM_INTENSITY;

    // Shadow factor
    float shadowFactor = shadowTrace(uv, waveIndex, time);

    // Combine
    float shading = ambient + shadowFactor * (diff + spec + rim);

    // Color interpolation based on waveIndex
    float alpha = waveIndex/(NUM_WAVES - 1.0);
    vec3 baseWaveColor = mix(colorFront, colorBack, alpha);

    return baseWaveColor * shading;
}

//////////////////////////////////////////////////////////////
// 8) mainImage: layering logic
//////////////////////////////////////////////////////////////

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 1) Normalize coords => [-1..1], preserve aspect
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    // 2) Camera angle transform
    uv = cameraTransform(uv, CAMERA_ANGLE);

    // 3) Time
    float time = iTime * ANIMATION_SPEED;

    // Track top wave
    float topZ     = -9999.0;
    float topIndex = -1.0;
    vec3 topColor  = vec3(0.0);

    // 4) Check each wave
    for(float i=0.0; i<NUM_WAVES; i+=1.0)
    {
        float zVal = getZValue(i);

        // Inside wave i?
        float distVal = waveSDF(uv, i, time);
        if(distVal < 0.0) // inside
        {
            if(zVal > topZ) 
            {
                topZ = zVal;
                topIndex = i;
                // compute lighting
                vec3 waveCol = waveLighting(uv, i, time);
                topColor = waveCol;
            }
        }
    }

    // 5) Background or top wave color
    vec3 finalColor = (topIndex < 0.0) ? bgColor : topColor;

    fragColor = vec4(finalColor, 1.0);
}
